import time,sys
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/dev')
import analyze as A
import z3
from fractions import Fraction
import stress_feas as SF
req=SF.gen(1,mode='feasible'); norm=A.validate(req)

# Build similar model but with a chosen fault set (from quick primary solve). Instead reuse internals by copy of solve logic minimal:
# We'll just get the initial model via A.solve but that's slow; use Optimize directly here replicating.
nodes=norm['nodes']; edges=norm['edges']; edge_ids=norm['edge_ids']; edge_index=norm['edge_index']
commodities=norm['commodities']; comm_ids=norm['comm_ids']; domains=norm['domains']; max_faults=norm['max_faults']; snaps=norm['snapshots']
nc=len(comm_ids); ne=len(edge_ids); ns=len(snaps); nd=len(domains)
W=[sum(w for (_,w) in c['routes']) for c in commodities]
from math import gcd
def lcm(a,b): return a//gcd(a,b)*b
L=1
for w in W: L=lcm(L,w)
coeff=[[0]*ne for _ in range(nc)]
for ci,c in enumerate(commodities):
    wc=W[ci]
    for (ed,w) in c['routes']:
        add=L*w//wc
        for eid in ed: coeff[ci][edge_index[eid]]+=add
q=[[z3.Int('q_%d_%d'%(s,ci)) for ci in range(nc)] for s in range(ns)]
base=[]
for s in range(ns):
    for ci in range(nc):
        lo,hi=snaps[s]['bounds'][ci]; base+= [q[s][ci]>=lo,q[s][ci]<=hi]
for s in range(ns):
    for e in range(ne):
        cap=edges[e]['capacity']; expr=None
        for ci in range(nc):
            cf=coeff[ci][e]
            if cf:
                t=cf*q[s][ci]; expr=t if expr is None else expr+t
        if expr is not None: base.append(expr<=L*cap)
def ve(s,metric,target):
    if metric=='demand': return L*q[s][comm_ids.index(target)]
    if metric=='link':
        e=edge_index[target]; expr=None
        for ci in range(nc):
            cf=coeff[ci][e]
            if cf:
                t=cf*q[s][ci]; expr=t if expr is None else expr+t
        return expr if expr is not None else z3.IntVal(0)
    expr=None
    for ci,c in enumerate(commodities):
        if (metric=='ingress' and c['source']==target) or (metric=='egress' and c['target']==target):
            t=L*q[s][ci]; expr=t if expr is None else expr+t
    return expr if expr is not None else z3.IntVal(0)
# choose S0 = one domain (arbitrary) to test pure LIA speed
S0=set([0,1,2])
for s in range(ns):
    for o in snaps[s]['observations']:
        expr=ve(s,o['metric'],o['target']); loL=L*o['lo']; hiL=L*o['hi']
        inside=z3.And(expr>=loL,expr<=hiL)
        if o['domain'] is None or domains.index(o['domain']) not in S0:
            base.append(inside)
        # else relaxed
t=time.time()
cnt=0
for s in range(ns):
    for ci in range(nc):
        o=z3.Optimize(); o.add(base); h=o.minimize(q[s][ci]); o.check(); o.lower(h); cnt+=1
        o=z3.Optimize(); o.add(base); h=o.maximize(q[s][ci]); o.check(); o.upper(h); cnt+=1
print('demand opts',cnt,'time',time.time()-t)
t=time.time();cnt=0
for s in range(ns):
    for e in range(ne):
        expr=None
        for ci in range(nc):
            cf=coeff[ci][e]
            if cf:
                tt=cf*q[s][ci]; expr=tt if expr is None else expr+tt
        if expr is None: continue
        o=z3.Optimize(); o.add(base); h=o.minimize(expr); o.check(); o.lower(h); cnt+=1
        o=z3.Optimize(); o.add(base); h=o.maximize(expr); o.check(); o.upper(h); cnt+=1
print('link opts',cnt,'time',time.time()-t)
